using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain any leftover notifications from other tests (static queue)
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain after test to prevent leaking into other tests
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
    {
        // Arrange & Act
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New Student 'John Doe' has been created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        // Arrange & Act
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE, "teacher");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course (ID: 101) has been updated", notification.Message);
        Assert.Equal("teacher", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        // Arrange & Act
        _sut.SendNotification("Department", "5", EntityOperation.DELETE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Student 'Alice' has been created")]
    [InlineData(EntityOperation.UPDATE, "Student 'Alice' has been updated")]
    [InlineData(EntityOperation.DELETE, "Student 'Alice' has been deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedMessage)
    {
        // Arrange & Act
        _sut.SendNotification("Student", "1", "Alice", operation, "user");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal(expectedMessage, notification.Message);
        Assert.Equal(operation.ToString(), notification.Operation);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        // Arrange
        var before = DateTime.Now;

        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var after = DateTime.Now;
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_MultipleNotifications_ReturnsFIFO()
    {
        // Arrange
        _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.NotNull(first);
        Assert.Equal("Student", first.EntityType);
        Assert.Equal("New Student 'First' has been created", first.Message);

        var second = _sut.ReceiveNotification();
        Assert.NotNull(second);
        Assert.Equal("Course", second.EntityType);
        Assert.Equal("Course 'Second' has been updated", second.Message);

        // Queue should be empty now
        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // Act & Assert (no-op implementation, should not throw)
        var exception = Record.Exception(() => _sut.MarkAsRead(42));
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdInMessage()
    {
        // Arrange & Act
        _sut.SendNotification("Student", "10", "  ", EntityOperation.CREATE, "user");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("New Student (ID: 10) has been created", notification.Message);
    }

    [Fact]
    public void Dispose_CanBeCalledMultipleTimes()
    {
        // Arrange
        var service = new NotificationService();

        // Act & Assert
        var exception = Record.Exception(() =>
        {
            service.Dispose();
            service.Dispose();
        });
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithoutDisplayNameOverload_UsesIdInMessage()
    {
        // Test the two-parameter overload that omits displayName
        // Arrange & Act
        _sut.SendNotification("Instructor", "7", EntityOperation.DELETE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor (ID: 7) has been deleted", notification.Message);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("7", notification.EntityId);
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_ValidInputs_SetsPageIndexAndTotalPages()
    {
        // Arrange
        var items = new List<string> { "a", "b", "c" };

        // Act
        var result = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, result.Count);
        Assert.Contains("a", result);
        Assert.Contains("b", result);
        Assert.Contains("c", result);
    }

    [Fact]
    public void Constructor_EmptyItems_CreatesEmptyList()
    {
        // Arrange & Act
        var result = new PaginatedList<int>(new List<int>(), 0, 1, 10);

        // Assert
        Assert.Empty(result);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        // Arrange & Act
        var result = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

        // Assert
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        // Arrange & Act
        var result = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

        // Assert
        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ReturnsFalse()
    {
        // Arrange & Act
        var result = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

        // Assert — TotalPages = ceil(10/5) = 2, PageIndex = 2
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_BeforeLastPage_ReturnsTrue()
    {
        // Arrange & Act
        var result = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

        // Assert — TotalPages = 2, PageIndex = 1
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_ReturnsCorrectPage()
    {
        // Arrange
        var source = Enumerable.Range(1, 20).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 5);

        // Assert — Page 2, items 6-10
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(4, result.TotalPages); // ceil(20/5) = 4
        Assert.Equal(5, result.Count);
        Assert.Equal(6, result[0]);
        Assert.Equal(7, result[1]);
        Assert.Equal(10, result[4]);
    }

    [Fact]
    public void Create_FirstPage_ReturnsFirstItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 15).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 5);

        // Assert
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(5, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(5, result[4]);
        Assert.True(result.HasNextPage);
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 12).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 3, 5);

        // Assert — Page 3 should have items 11, 12
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(2, result.Count);
        Assert.Equal(11, result[0]);
        Assert.Equal(12, result[1]);
        Assert.False(result.HasNextPage);
        Assert.True(result.HasPreviousPage);
    }

    [Theory]
    [InlineData(1, 10, 1)]   // 1 item, page size 10 = 1 total page
    [InlineData(10, 10, 1)]  // 10 items, page size 10 = 1 total page
    [InlineData(11, 10, 2)]  // 11 items, page size 10 = 2 total pages
    [InlineData(20, 10, 2)]  // 20 items, page size 10 = 2 total pages
    [InlineData(21, 10, 3)]  // 21 items, page size 10 = 3 total pages
    public void TotalPages_CalculatesCorrectly(int totalItems, int pageSize, int expectedTotalPages)
    {
        // Arrange & Act
        var result = new PaginatedList<int>(new List<int>(), totalItems, 1, pageSize);

        // Assert
        Assert.Equal(expectedTotalPages, result.TotalPages);
    }
}

