using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student CreateTestStudent(string firstName = "John", string lastName = "Doe", DateTime? enrollmentDate = null)
    {
        var student = new Student
        {
            FirstMidName = firstName,
            LastName = lastName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    #region Index

    [Fact]
    public void Index_NoParameters_ReturnsViewWithStudents()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");
        CreateTestStudent("Bob", "Jones");

        // Act
        var result = _controller.Index(null, null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_WithSearchString_FiltersStudents()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");
        CreateTestStudent("Bob", "Johnson");

        // Act
        var result = _controller.Index(null, null, "Smith", null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersCorrectly()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");
        CreateTestStudent("Bob", "Johnson");

        // Act
        var result = _controller.Index(null, null, "Alice", null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Alice", model[0].FirstMidName);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        // Arrange
        CreateTestStudent("Alice", "Anderson");
        CreateTestStudent("Bob", "Zimmerman");

        // Act
        var result = _controller.Index("name_desc", null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Zimmerman", model[0].LastName);
        Assert.Equal("Anderson", model[1].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        // Arrange
        CreateTestStudent("Alice", "First", new DateTime(2023, 1, 1));
        CreateTestStudent("Bob", "Second", new DateTime(2020, 1, 1));

        // Act
        var result = _controller.Index("Date", null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Second", model[0].LastName);
        Assert.Equal("First", model[1].LastName);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        // Arrange
        CreateTestStudent("Alice", "First", new DateTime(2023, 1, 1));
        CreateTestStudent("Bob", "Second", new DateTime(2020, 1, 1));

        // Act
        var result = _controller.Index("date_desc", null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("First", model[0].LastName);
        Assert.Equal("Second", model[1].LastName);
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        // Arrange
        CreateTestStudent("Bob", "Zimmerman");
        CreateTestStudent("Alice", "Anderson");

        // Act
        var result = _controller.Index(null, null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Anderson", model[0].LastName);
        Assert.Equal("Zimmerman", model[1].LastName);
    }

    [Fact]
    public void Index_SearchStringResetsPaging()
    {
        // Arrange - add enough students for pagination
        for (int i = 0; i < 12; i++)
        {
            CreateTestStudent($"Student{i}", $"Last{i:D2}");
        }

        // Act — new searchString should reset page to 1
        var result = _controller.Index(null, null, "Student", null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchUsesCurrentFilter()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");
        CreateTestStudent("Bob", "Johnson");

        // Act — searchString is null, currentFilter is "Smith"
        var result = _controller.Index(null, "Smith", null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    #endregion

    #region Details

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = CreateTestStudent("Alice", "Smith");

        // Act
        var result = _controller.Details(student.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Alice", model.FirstMidName);
        Assert.Equal("Smith", model.LastName);
        Assert.Equal(student.ID, model.ID);
    }

    #endregion

    #region Create GET

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        // Act
        var result = _controller.Create();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    #endregion

    #region Create POST

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);

        // Verify student was saved
        Assert.Single(_context.Students);
        Assert.Equal("Test", _context.Students.First().FirstMidName);
    }

    [Fact]
    public void Create_Post_MinValueEnrollmentDate_ReturnsViewWithError()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsViewWithStudent()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };
        _controller.ModelState.AddModelError("LastName", "Required");

        // Act
        var result = _controller.Create(student);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Same(student, viewResult.Model);
    }

    #endregion

    #region Edit GET

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Edit((int?)null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Edit(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = CreateTestStudent("Alice", "Smith");

        // Act
        var result = _controller.Edit(student.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Alice", model.FirstMidName);
    }

    #endregion

    #region Edit POST

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        // Arrange
        var student = CreateTestStudent("Alice", "Smith");
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var updatedStudent = new Student
        {
            ID = student.ID,
            FirstMidName = "Alice Updated",
            LastName = "Smith",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        var result = _controller.Edit(updatedStudent);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_Post_MinDateEnrollment_ReturnsViewWithError()
    {
        // Arrange
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        // Act
        var result = _controller.Edit(student);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsViewWithStudent()
    {
        // Arrange
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };
        _controller.ModelState.AddModelError("LastName", "Required");

        // Act
        var result = _controller.Edit(student);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Same(student, viewResult.Model);
    }

    #endregion

    #region Delete GET

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = CreateTestStudent("Alice", "Smith");

        // Act
        var result = _controller.Delete(student.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Alice", model.FirstMidName);
    }

    #endregion

    #region DeleteConfirmed

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        // Arrange
        var student = CreateTestStudent("Alice", "Smith");
        var id = student.ID;

        // Act
        var result = _controller.DeleteConfirmed(id);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
