+        // Arrange & Act
+        var model = new AssignedCourseData
+        {
+            CourseID = 1050,
+            Title = "Chemistry",
+            Assigned = true
+        };
+
+        // Assert
+        Assert.Equal(1050, model.CourseID);
+        Assert.Equal("Chemistry", model.Title);
+        Assert.True(model.Assigned);
+    }
+
+    [Fact]
+    public void AssignedCourseData_AssignedDefaultsFalse()
+    {
+        // Arrange & Act
+        var model = new AssignedCourseData();
+
+        // Assert
+        Assert.False(model.Assigned);
+    }
+
+    [Fact]
+    public void EnrollmentDateGroup_PropertiesCanBeSet()
+    {
+        // Arrange
+        var date = new DateTime(2023, 9, 1);
+
+        // Act
+        var model = new EnrollmentDateGroup
+        {
+            EnrollmentDate = date,
+            StudentCount = 15
+        };
+
+        // Assert
+        Assert.Equal(date, model.EnrollmentDate);
+        Assert.Equal(15, model.StudentCount);
+    }
+
+    [Fact]
+    public void EnrollmentDateGroup_EnrollmentDateIsNullable()
+    {
+        // Arrange & Act
+        var model = new EnrollmentDateGroup { EnrollmentDate = null };
+
+        // Assert
+        Assert.Null(model.EnrollmentDate);
+    }
+
+    [Fact]
+    public void InstructorIndexData_PropertiesCanBeSet()
+    {
+        // Arrange & Act
+        var model = new InstructorIndexData
+        {
+            Instructors = new List<ContosoUniversity.Models.Instructor>(),
+            Courses = new List<ContosoUniversity.Models.Course>(),
+            Enrollments = new List<ContosoUniversity.Models.Enrollment>()
+        };
+
+        // Assert
+        Assert.NotNull(model.Instructors);
+        Assert.NotNull(model.Courses);
+        Assert.NotNull(model.Enrollments);
+        Assert.Empty(model.Instructors);
+        Assert.Empty(model.Courses);
+        Assert.Empty(model.Enrollments);
+    }
+}
